// optionalTestDeps matches the fakeplugin fixture's cookie pair (the only
// buildable plugin subprocess the tests can launch).
func optionalTestDeps() plugin.Deps {
	return plugin.Deps{
		MagicCookieKey:   "MELLIFERA_TEST_COOKIE",
		MagicCookieValue: "test-secret",
		CoreVersion:      "0.1.0",
	}
}

// optionalScannerCaps is the capability set the fakeplugin fixture declares.
func optionalScannerCaps() []sdk.Capability {
	return []sdk.Capability{{Type: "scanner", ID: "default", ProtoService: "mellifera.scanner.v1.Scanner"}}
}

// buildOptionalBinary builds the internal/plugin fakeplugin fixture to a temp
// binary. go test runs the test binary with cwd = this package dir, so the
// ../../ path resolves; the explicit-path build is not skipped by the
// testdata rule (only ./... matching is).
func buildOptionalBinary(t *testing.T) string {
	t.Helper()
	out := filepath.Join(t.TempDir(), "fakeplugin")
	cmd := exec.Command("go", "build", "-o", out, "../../internal/plugin/testdata/fakeplugin")
	cmd.Env = append(os.Environ(), "CGO_ENABLED=0")
	if b, err := cmd.CombinedOutput(); err != nil {
		t.Fatalf("build fakeplugin: %v\n%s", err, b)
	}
	return out
}

// TestSourceCatalogExternalRowsSynthesized pins the catalog synthesis: the
// parsed env pairs append generic optional rows (name = the id itself, the
// description constant) AFTER the boot-literal rows and in declaration order,
// while the literal rows stay byte-identical; an absent declaration
// synthesizes nothing.
func TestSourceCatalogExternalRowsSynthesized(t *testing.T) {
	t.Setenv("MELLIFERA_EXTRA_PLUGINS", "ext-one=bin/ext-one, ext-two=/opt/ext-two")
	catalog := appendExternalRows(sourceCatalog, parseExtraPlugins(os.Getenv("MELLIFERA_EXTRA_PLUGINS")))

	if len(catalog) != len(sourceCatalog)+2 {
		t.Fatalf("catalog len = %d, want %d (base + 2 externals)", len(catalog), len(sourceCatalog)+2)
	}
	for i, base := range sourceCatalog {
		if catalog[i] != base {
			t.Errorf("catalog[%d] = %+v, want the untouched base row %+v", i, catalog[i], base)
		}
	}
	externals := catalog[len(sourceCatalog):]
	wantIDs := []string{"ext-one", "ext-two"}
	for i, row := range externals {
		if row.id != wantIDs[i] {
			t.Errorf("external[%d].id = %q, want %q (declaration order)", i, row.id, wantIDs[i])
		}
		if row.name != row.id {
			t.Errorf("external[%d].name = %q, want the id itself %q", i, row.name, row.id)
		}
		if row.description != externalPluginDescription {
			t.Errorf("external[%d].description = %q, want %q", i, row.description, externalPluginDescription)
		}
		if !row.optional {
			t.Errorf("external[%d].optional = false, want true", i)
		}
	}

	empty := appendExternalRows(sourceCatalog, parseExtraPlugins(""))
	if len(empty) != len(sourceCatalog) {
		t.Errorf("absent declaration grew the catalog to %d rows, want %d", len(empty), len(sourceCatalog))
	}
}

// TestOptionalLoadAbsentRecordsNotServing pins the absent-binary branch: one
// synthesized not_serving row naming the absence, Load/Start never run (the
// manager still answers notLoadedErr for the id), and the status assembly
// consults the synthesized row FIRST — manager-first would drop the row
// entirely.
func TestOptionalLoadAbsentRecordsNotServing(t *testing.T) {
	absent := filepath.Join(t.TempDir(), "ext-absent")
	t.Setenv("MELLIFERA_EXTRA_PLUGINS", "ext-absent="+absent)
	extras := parseExtraPlugins(os.Getenv("MELLIFERA_EXTRA_PLUGINS"))
	if len(extras) != 1 {
		t.Fatalf("parseExtraPlugins produced %d pairs, want 1", len(extras))
	}

	mgr := plugin.Open(optionalTestDeps())
	optionalState := make(map[string]api.PluginHealth)
	loadedCaps := make(map[string][]string)
	for _, p := range extras {
		loadOptionalPlugin(context.Background(), mgr, p.id, p.path, optionalScannerCaps(), optionalState, loadedCaps)
	}

	row, ok := optionalState["ext-absent"]
	if !ok {
		t.Fatal("optionalState: no synthesized row for the absent binary")
	}
	if row.State != "not_serving" {
		t.Errorf("row.State = %q, want not_serving", row.State)
	}
	if !strings.Contains(row.Message, absent) {
		t.Errorf("row.Message = %q, want it to name the absent path %q", row.Message, absent)
	}
	if _, err := mgr.Status("ext-absent"); err == nil {
		t.Error("mgr.Status on the absent id succeeded — the absent branch must never Load")
	}
	if len(loadedCaps) != 0 {
		t.Errorf("loadedCaps = %v, want empty (never loaded)", loadedCaps)
	}

	// The consult-first law, behaviorally: the synthesized row reaches the
	// status assembly even though the manager has no entry for the id.
	healths := pluginHealths([]string{"ext-absent"}, optionalState, mgr)
	if len(healths) != 1 || healths[0].ID != "ext-absent" || healths[0].State != "not_serving" {
		t.Errorf("pluginHealths = %+v, want the single synthesized not_serving row", healths)
	}
}

// TestOptionalLoadBrokenRecordsFailed pins the skip-and-report branch: a
// present-but-broken binary (Load or Start error) stays boot-green — one
// synthesized failed row carrying the error message — and never joins
// loadedCaps (the shutdown set).
func TestOptionalLoadBrokenRecordsFailed(t *testing.T) {
	// Present to os.Stat, but not a plugin binary: Load registers it, Start's
	// subprocess launch fails.
	broken := filepath.Join(t.TempDir(), "ext-broken")
	if err := os.WriteFile(broken, []byte("not a plugin binary\n"), 0o644); err != nil {
		t.Fatalf("write broken binary: %v", err)
	}
	t.Setenv("MELLIFERA_EXTRA_PLUGINS", "ext-broken="+broken)
	extras := parseExtraPlugins(os.Getenv("MELLIFERA_EXTRA_PLUGINS"))
	if len(extras) != 1 {
		t.Fatalf("parseExtraPlugins produced %d pairs, want 1", len(extras))
	}

	mgr := plugin.Open(optionalTestDeps())
	optionalState := make(map[string]api.PluginHealth)
	loadedCaps := make(map[string][]string)
	for _, p := range extras {
		loadOptionalPlugin(context.Background(), mgr, p.id, p.path, optionalScannerCaps(), optionalState, loadedCaps)
	}

	row, ok := optionalState["ext-broken"]
	if !ok {
		t.Fatal("optionalState: no synthesized row for the broken binary")
	}
	if row.State != "failed" {
		t.Errorf("row.State = %q, want failed", row.State)
	}
	if row.Message == "" {
		t.Error("row.Message empty — the failed row must carry the error")
	}
	if len(loadedCaps) != 0 {
		t.Errorf("loadedCaps = %v, want empty (start failed)", loadedCaps)
	}

	healths := pluginHealths([]string{"ext-broken"}, optionalState, mgr)
	if len(healths) != 1 || healths[0].State != "failed" {
		t.Errorf("pluginHealths = %+v, want the single synthesized failed row", healths)
	}
}

// TestOptionalLoadPresentStarts pins the present branch: Load+Start run as
// today, no synthesized row is kept (the manager serves the status), and the
// capability types join loadedCaps like any in-repo load.
func TestOptionalLoadPresentStarts(t *testing.T) {
	mgr := plugin.Open(optionalTestDeps())
	optionalState := make(map[string]api.PluginHealth)
	loadedCaps := make(map[string][]string)

	bin := buildOptionalBinary(t)
	t.Setenv("MELLIFERA_EXTRA_PLUGINS", "ext-present="+bin)
	extras := parseExtraPlugins(os.Getenv("MELLIFERA_EXTRA_PLUGINS"))
	if len(extras) != 1 {
		t.Fatalf("parseExtraPlugins produced %d pairs, want 1", len(extras))
	}
	for _, p := range extras {
		loadOptionalPlugin(context.Background(), mgr, p.id, p.path, optionalScannerCaps(), optionalState, loadedCaps)
	}

	if len(optionalState) != 0 {
		t.Errorf("optionalState = %v, want empty (present-and-started rides the manager path)", optionalState)
	}
	got, ok := loadedCaps["ext-present"]
	if !ok || len(got) != 1 || got[0] != "scanner" {
		t.Errorf("loadedCaps[ext-present] = %v (ok=%v), want [scanner]", got, ok)
	}
	deadline := time.Now().Add(10 * time.Second)
	for {
		h, err := mgr.Status("ext-present")
		if err != nil {
			t.Fatalf("mgr.Status on the present id: %v", err)
		}
		if h.State == "serving" {
			break
		}
		if time.Now().After(deadline) {
			t.Fatalf("plugin state = %q, want serving after Start", h.State)
		}
		time.Sleep(100 * time.Millisecond)
	}
}

// TestShutdownSkipsNeverLoaded pins the shutdown filter: the loop stops only
// the ids that actually loaded, in catalog order — a never-loaded optional id
// (absent, or Load/Start-failed) gets no stop attempt.
func TestShutdownSkipsNeverLoaded(t *testing.T) {
	t.Setenv("MELLIFERA_EXTRA_PLUGINS", "ext-one=bin/ext-one, ext-two=bin/ext-two")
	extras := parseExtraPlugins(os.Getenv("MELLIFERA_EXTRA_PLUGINS"))
	pluginIDs := []string{"base-scanner"}
	for _, p := range extras {
		pluginIDs = append(pluginIDs, p.id)
	}
	pluginIDs = append(pluginIDs, "shikimori")
	loadedCaps := map[string][]string{
		"base-scanner": {"scanner"},
		"shikimori":    {"metadata_source"},
	}

	got := stoppableIDs(pluginIDs, loadedCaps)
	want := []string{"base-scanner", "shikimori"}
	if len(got) != len(want) {
		t.Fatalf("stoppableIDs = %v, want %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Errorf("stoppableIDs[%d] = %q, want %q", i, got[i], want[i])
		}
	}
}

// TestInRepoLoadStaysFatal pins the in-repo discipline against drift: the
// loadPlugin closure keeps the fail-fast fatal pair byte-for-byte, the eight
// in-repo ids load through it, the optional site stays the ONE generic loop
// over the parsed env list (no per-plugin call sites), and the core stays
// plugin-neutral — no per-plugin vocabulary anywhere in main.go.
func TestInRepoLoadStaysFatal(t *testing.T) {
	src, err := os.ReadFile("main.go")
	if err != nil {
		t.Fatalf("read main.go: %v", err)
	}
	body := string(src)

	const fatalPair = `loadPlugin := func(pluginID, binaryPath string, caps []sdk.Capability) {
		fatalOn(mgr.Load(pluginID, binaryPath, caps), "load "+pluginID)
		fatalOn(mgr.Start(ctx, pluginID), "start "+pluginID)`
	if !strings.Contains(body, fatalPair) {
		t.Error("the loadPlugin fatal pair drifted — in-repo loads must keep the fail-fast pair byte-for-byte")
	}

	inRepo := []string{
		`loadPlugin("base-scanner"`,
		`loadPlugin("serial-scanner"`,
		`loadPlugin("tv-parser"`,
		`loadPlugin("image-enricher"`,
		`loadPlugin("serial-parser"`,
		`loadPlugin("frame-grabber"`,
		`loadPlugin("shikimori"`,
		`loadPlugin(module.PluginIDTmdb`,
	}
	for _, marker := range inRepo {
		if n := strings.Count(body, marker); n != 1 {
			t.Errorf("%q appears %d times, want exactly 1", marker, n)
		}
	}
	if n := strings.Count(body, "for _, p := range cfg.extraPlugins {"); n != 1 {
		t.Errorf("the generic optional loop appears %d times, want exactly 1", n)
	}
	// No in-repo id may sneak onto the optional site; a named optional call
	// site (any loadPluginOptional invocation outside the loop) is drift.
	for _, line := range strings.Split(body, "\n") {
		if !strings.Contains(line, "loadPluginOptional(") || strings.Contains(line, "loadPluginOptional := func") {
			continue
		}
		for _, id := range []string{"base-scanner", "serial-scanner", "tv-parser", "image-enricher", "serial-parser", "frame-grabber", "shikimori", "PluginIDTmdb"} {
			if strings.Contains(line, id) {
				t.Errorf("optional load site carries the in-repo id %q: %s", id, line)
			}
		}
	}
	if i := strings.Index(strings.ToLower(body), "jav"); i >= 0 {
		end := i + 20
		if end > len(body) {
			end = len(body)
		}
		t.Errorf("main.go carries per-plugin vocabulary at offset %d: %q", i, body[max(0, i-20):end])
	}
}

// promotionFixture opens a real store + module registry on a temp file — the
// registry auto-seeds the tv chain, so the promotion tests must stay agnostic
// of the seeded chain's length and any specialized binding id: they snapshot
// the pre-promotion rows and assert only the promoted ones.
func promotionFixture(t *testing.T) *module.Registry {
	t.Helper()
	ctx := context.Background()
	st, err := store.Open(ctx, filepath.Join(t.TempDir(), "promotion.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = st.Close() })
	reg, err := module.Open(ctx, st)
	if err != nil {
		t.Fatalf("module.Open: %v", err)
	}
	return reg
}

// promotionChain reads the tv module's live metadata_sources chain.
func promotionChain(t *testing.T, reg *module.Registry) []module.MetadataSourceBinding {
	t.Helper()
	m, err := reg.Get("tv")
	if err != nil {
		t.Fatalf("reg.Get(tv): %v", err)
	}
	return m.MetadataSources
}

// findPromotedRow locates one promoted row by plugin id.
func findPromotedRow(chain []module.MetadataSourceBinding, pluginID string) (module.MetadataSourceBinding, bool) {
	for _, b := range chain {
		if b.PluginID == pluginID {
			return b, true
		}
	}
	return module.MetadataSourceBinding{}, false
}

// TestPromotionInsertsEnvDeclaredExternals pins the happy path: one binding
// per declared external id, in declaration order, each inserted after the
// chain's current max priority (+1 per binding); the shared posture fields
// are fixed (capability default, enabled, no_relay, no options), and every
// pre-existing chain row survives byte-for-byte.
func TestPromotionInsertsEnvDeclaredExternals(t *testing.T) {
	reg := promotionFixture(t)
	before := promotionChain(t, reg)
	baseMax := 0
	for _, b := range before {
		if b.Priority > baseMax {
			baseMax = b.Priority
		}
	}

	extras := []extraPlugin{{id: "ext-one", path: "bin/ext-one"}, {id: "ext-two", path: "bin/ext-two"}}
	loadedCaps := map[string][]string{"ext-one": {"metadata_source"}, "ext-two": {"metadata_source"}}
	promoteExternalBindings(reg, extras, loadedCaps, func(string) []string { return nil })

	after := promotionChain(t, reg)
	if len(after) != len(before)+2 {
		t.Fatalf("chain grew to %d rows, want %d (base + 2 promoted)", len(after), len(before)+2)
	}
	for i := range before {
		if !reflect.DeepEqual(after[i], before[i]) {
			t.Errorf("chain[%d] changed under promotion: %+v, want %+v", i, after[i], before[i])
		}
	}
	for i, id := range []string{"ext-one", "ext-two"} {
		row, ok := findPromotedRow(after, id)
		if !ok {
			t.Fatalf("no promoted row for %q", id)
		}
		if row.Priority != baseMax+1+i {
			t.Errorf("%s.Priority = %d, want %d (after the chain's max, +1 per binding)", id, row.Priority, baseMax+1+i)
		}
		if row.CapabilityID != "default" {
			t.Errorf("%s.CapabilityID = %q, want default", id, row.CapabilityID)
		}
		if !row.Enabled {
			t.Errorf("%s.Enabled = false, want true", id)
		}
		if !row.NoRelay {
			t.Errorf("%s.NoRelay = false, want true", id)
		}
		// The display walk reads the binding's display fields; a promoted
		// row without them leaves anchored items on filename titles.
		if want := []string{"title", "parsed_from"}; !reflect.DeepEqual(row.DisplayFields, want) {
			t.Errorf("%s.DisplayFields = %v, want %v (the generic enrichment shape)", id, row.DisplayFields, want)
		}
		// The registry's storage law persists a nil Options as the empty
		// object; the pin is that promotion writes no option MATERIAL.
		var opts map[string]any
		if err := json.Unmarshal(row.Options, &opts); err != nil || len(opts) != 0 {
			t.Errorf("%s.Options = %s, want the empty object (promotion never writes options)", id, row.Options)
		}
	}
	first, _ := findPromotedRow(after, "ext-one")
	second, _ := findPromotedRow(after, "ext-two")
	if first.Priority >= second.Priority {
		t.Errorf("declaration order lost: ext-one priority %d not below ext-two's %d", first.Priority, second.Priority)
	}
}

// TestPromotionServerFromDeclaredSecrets pins the SERVER derivation AND the
// re-derivation law: a loaded id that declared secrets in its handshake
// promotes SERVER; boot 1 (declared-but-absent) promoted the same id LOCAL,
// the operator then set the secret option, and boot 2 (loaded + declared
// secrets) flips the posture to SERVER in place — priority and option values
// untouched, no operator action beyond the original promotion.
func TestPromotionServerFromDeclaredSecrets(t *testing.T) {
	reg := promotionFixture(t)
	extras := []extraPlugin{{id: "ext-secrets", path: "bin/ext-secrets"}}
	withSecrets := func(string) []string { return []string{"api_key"} }
	loadedCaps := map[string][]string{"ext-secrets": {"metadata_source"}}

	// Boot 1: declared but absent — the row exists, LOCAL, dormant.
	promoteExternalBindings(reg, extras, nil, withSecrets)
	row, ok := findPromotedRow(promotionChain(t, reg), "ext-secrets")
	if !ok {
		t.Fatal("boot 1: no promoted row for the declared id")
	}
	if row.AuthMode != "" {
		t.Fatalf("boot 1: AuthMode = %q, want empty (never loaded)", row.AuthMode)
	}
	priority := row.Priority

	// The operator sets the secret option against the promoted row.
	if err := reg.SetBindingOptions(context.Background(), "tv", "ext-secrets", json.RawMessage(`{"api_key":"sk"}`)); err != nil {
		t.Fatalf("SetBindingOptions: %v", err)
	}

	// Boot 2: the binary loaded and declared secrets — SERVER engages.
	promoteExternalBindings(reg, extras, loadedCaps, withSecrets)
	row, ok = findPromotedRow(promotionChain(t, reg), "ext-secrets")
	if !ok {
		t.Fatal("boot 2: promoted row vanished")
	}
	if row.AuthMode != "SERVER" {
		t.Errorf("boot 2: AuthMode = %q, want SERVER", row.AuthMode)
	}
	if row.Priority != priority {
		t.Errorf("boot 2: Priority = %d, want the untouched %d", row.Priority, priority)
	}
	if string(row.Options) != `{"api_key":"sk"}` {
		t.Errorf("boot 2: Options = %s, want the operator's value untouched", row.Options)
	}
}

// TestPromotionLocalWithoutSecrets pins the LOCAL posture table: a loaded id
// that declared no metadata_source secrets stays empty, and so does a
// never-loaded id even when the secrets stub would answer (the loaded guard
// is a conjunction, not the secrets lookup alone).
func TestPromotionLocalWithoutSecrets(t *testing.T) {
	reg := promotionFixture(t)
	extras := []extraPlugin{{id: "ext-bare", path: "bin/ext-bare"}, {id: "ext-gone", path: "bin/ext-gone"}}
	loadedCaps := map[string][]string{"ext-bare": {"metadata_source"}}
	withSecrets := func(id string) []string {
		if id == "ext-gone" {
			return []string{"api_key"}
		}
		return nil
	}
	promoteExternalBindings(reg, extras, loadedCaps, withSecrets)

	for _, tc := range []struct {
		id     string
		why    string
		loaded bool
	}{
		{"ext-bare", "loaded without declared secrets", true},
		{"ext-gone", "declared secrets but never loaded", false},
	} {
		row, ok := findPromotedRow(promotionChain(t, reg), tc.id)
		if !ok {
			t.Fatalf("%s: no promoted row", tc.id)
		}
		if row.AuthMode != "" {
			t.Errorf("%s (%s): AuthMode = %q, want empty", tc.id, tc.why, row.AuthMode)
		}
	}
}

// TestPromotionAbsentStillPromoted pins the absent-binary law: a declared id
// whose binary never deployed still gets its chain row — enabled, no_relay,
// LOCAL — dormant via the unavailable law, inserted after the chain's max
// priority like any other promotion.
func TestPromotionAbsentStillPromoted(t *testing.T) {
	reg := promotionFixture(t)
	before := promotionChain(t, reg)
	baseMax := 0
	for _, b := range before {
		if b.Priority > baseMax {
			baseMax = b.Priority
		}
	}

	extras := []extraPlugin{{id: "ext-absent", path: "bin/ext-absent"}}
	promoteExternalBindings(reg, extras, nil, func(string) []string { return nil })

	row, ok := findPromotedRow(promotionChain(t, reg), "ext-absent")
	if !ok {
		t.Fatal("no promoted row for the declared-but-absent id")
	}
	if row.Priority != baseMax+1 {
		t.Errorf("Priority = %d, want %d (after the chain's max)", row.Priority, baseMax+1)
	}
	if row.CapabilityID != "default" || !row.Enabled || !row.NoRelay || row.AuthMode != "" {
		t.Errorf("posture drifted: %+v, want default/enabled/no_relay/LOCAL", row)
	}
}
